ServerEvents.recipes(function (event) {
	var vahtaFailed = 0
	// ['2x a', '#b'] -> ['a', 'a', '#b']
	var vahtaExpand = function (list) {
		var res = []
		for (var k = 0; k < list.length; k++) {
			var m = typeof list[k] === 'string' ? /^(\d+)x (.+)$/.exec(list[k]) : null
			if (!m) { res.push(nsIng(list[k])); continue }
			for (var n = 0; n < parseInt(m[1], 10); n++) res.push(nsIng(m[2]))
		}
		return res
	}
	for (var vahtaI = 0; vahtaI < vahtaMixRecipes.length; vahtaI++) {
		var vahtaM = vahtaMixRecipes[vahtaI]
		try {
			event.recipes.create.mixing(vahtaM[1], vahtaExpand(vahtaM[2])).id(vahtaM[0])
		} catch (vahtaErr) {
			vahtaFailed++
			console.warn('[vahta] mixing ' + vahtaM[0] + ': ' + vahtaErr)
		}
	}
	for (var vahtaJ = 0; vahtaJ < vahtaCutRecipes.length; vahtaJ++) {
		var vahtaC = vahtaCutRecipes[vahtaJ]
		try {
			event.recipes.create.cutting(vahtaC[1], nsIng(vahtaC[2])).id(vahtaC[0])
		} catch (vahtaErr2) {
			vahtaFailed++
			console.warn('[vahta] cutting ' + vahtaC[0] + ': ' + vahtaErr2)
		}
	}
	console.info('[vahta] машинные рецепты: mixing ' + vahtaMixRecipes.length + ', cutting ' + vahtaCutRecipes.length + ', ошибок ' + vahtaFailed)
})
